/// <summary>
/// Extension of SalesFormLetter_Invoice to apply Catch Weight (CW) credit logic during return order invoicing.
/// </summary>
[ExtensionOf(classStr(SalesFormLetter_Invoice))]
final class METSalesFormLetter_Invoice_Extension
{
}

Method.Source:
/// <summary>
/// Overrides the run method to block invoicing for certain customers and apply CW credit logic for return orders.
/// </summary>
public void run()
{
    SalesTable salesTableLocal = this.salesTable();

    // Block invoicing if customer is flagged
    CustVendorBlocked blockStatus = CustTable::find(salesTableLocal.CustAccount).Blocked;
    if (blockStatus == CustVendorBlocked::METSalesinvoice)
    {
        throw warning(strFmt("@SYS18389", salesTableLocal.CustAccount, enum2Str(blockStatus)));
    }

    // Proceed with standard invoice logic
    next run();
}
